public interface ProviderInterface {
    
    /**
     * Catch-up (timeshift) for a past programme. start = unix seconds, duration in minutes.
     * v9's client build left out `stream=`, which broke catch-up on the APK.
     */
    fun `catchupUrl`(`streamId`: kotlin.String, `start`: kotlin.Long, `durationMin`: kotlin.UInt): kotlin.String
    
    fun `categories`(`kind`: ContentKind): List<Category>
    
    /**
     * None = every channel.
     */
    fun `channels`(`categoryId`: kotlin.String?): List<Channel>
    
    /**
     * Channels for the given ids, in that order (favorites, recently watched).
     */
    fun `channelsByIds`(`ids`: List<kotlin.String>): List<Channel>
    
    /**
