     * wrong), provider as fallback. Cached 30 min per channel.
     */
    fun `epg`(`streamId`: kotlin.String): List<Programme>
    
    fun `episodeUrl`(`episodeId`: kotlin.String, `extension`: kotlin.String?): kotlin.String
    
    /**
     * All episodes of a series, sorted by season then episode.
     */
    fun `episodes`(`seriesId`: kotlin.String): List<Episode>
    
    fun `liveUrl`(`streamId`: kotlin.String): kotlin.String
    
    /**
     * Returns false when there is no cache, or it belongs to another playlist.
     */
    fun `load`(`path`: kotlin.String): kotlin.Boolean
    
    /**
     * Checks the login. Network failures and bad credentials are separate errors.
     */
    fun `login`(): AccountInfo
    
    fun `movieUrl`(`streamId`: kotlin.String, `extension`: kotlin.String?): kotlin.String
    
    fun `movies`(`categoryId`: kotlin.String?): List<Movie>
    
    fun `moviesByIds`(`ids`: List<kotlin.String>): List<Movie>
    
    fun `recentlyAddedMovies`(`limit`: kotlin.UInt): List<Movie>
    
    fun `recentlyAddedSeries`(`limit`: kotlin.UInt): List<Series>
    
    /**
     * Persist the catalog so the next launch shows content instantly.
     */
    fun `save`(`path`: kotlin.String)
    
    /**
     * Case/accent-insensitive substring search; best matches (prefix) first.
     */
    fun `search`(`query`: kotlin.String, `limit`: kotlin.UInt): SearchResults
    
    fun `series`(`categoryId`: kotlin.String?): List<Series>
    
    fun `seriesByIds`(`ids`: List<kotlin.String>): List<Series>
    
    /**
