 */
public object FfiConverterTypeProvider: FfiConverter<Provider, Pointer> {

    override fun lower(value: Provider): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Provider {
        return Provider(value)
    }

    override fun read(buf: ByteBuffer): Provider {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Provider) = 8UL

    override fun write(value: Provider, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


