/**
 * @suppress
 */
public object FfiConverterTypeUserStore: FfiConverter<UserStore, Pointer> {

    override fun lower(value: UserStore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): UserStore {
        return UserStore(value)
    }

    override fun read(buf: ByteBuffer): UserStore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: UserStore) = 8UL

    override fun write(value: UserStore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



